import type { Html } from "foldkit/html";
import { html } from "foldkit/html";

import {
  otpFieldInputClassName,
  otpFieldInputGroupClassName,
  otpFieldRootClassName,
  otpFieldSeparatorClassName,
} from "./view";

export {
  otpFieldInputClassName,
  otpFieldInputGroupClassName,
  otpFieldRootClassName,
  otpFieldSeparatorClassName,
} from "./view";

export type OtpFieldStyle = Readonly<Record<string, string>>;

export type OtpFieldState = Readonly<{
  disabled?: boolean | undefined;
  invalid?: boolean | undefined;
}>;

export type RootViewConfig = OtpFieldState &
  Readonly<{
    children: readonly Html[];
    className?: string | undefined;
    style?: OtpFieldStyle | undefined;
  }>;

export type InputGroupViewConfig = OtpFieldState &
  Readonly<{
    children: readonly Html[];
    ariaLabel: string;
    className?: string | undefined;
    style?: OtpFieldStyle | undefined;
  }>;

export type InputViewConfig<ParentMessage> = OtpFieldState &
  Readonly<{
    id: string;
    value: string;
    index: number;
    onInput: (value: string, index: number) => ParentMessage;
    ariaLabel: string;
    name?: string | undefined;
    className?: string | undefined;
    style?: OtpFieldStyle | undefined;
  }>;

export type SeparatorViewConfig = Readonly<{
  label?: string | undefined;
  className?: string | undefined;
  style?: OtpFieldStyle | undefined;
}>;

const classNames = (base: string, className?: string): string =>
  [base, className]
    .filter((value): value is string => value !== undefined && value !== "")
    .join(" ");

const stateAttributes = <ParentMessage>(
  h: ReturnType<typeof html<ParentMessage>>,
  state: OtpFieldState
) => [
  ...(state.disabled === true ? [h.DataAttribute("disabled", "")] : []),
  ...(state.invalid === true ? [h.DataAttribute("invalid", "")] : []),
];

export const rootView = <ParentMessage>({
  children,
  className,
  style,
  ...state
}: RootViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...stateAttributes(h, state),
      h.Class(classNames(otpFieldRootClassName, className)),
      h.Style(style ?? {}),
    ],
    children
  );
};

export const inputGroupView = <ParentMessage>({
  children,
  ariaLabel,
  className,
  style,
  ...state
}: InputGroupViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.div(
    [
      ...stateAttributes(h, state),
      h.Role("group"),
      h.AriaLabel(ariaLabel),
      h.Class(classNames(otpFieldInputGroupClassName, className)),
      h.Style(style ?? {}),
    ],
    children
  );
};

export const inputView = <ParentMessage>({
  id,
  value,
  index,
  onInput,
  ariaLabel,
  name,
  className,
  style,
  ...state
}: InputViewConfig<ParentMessage>): Html => {
  const h = html<ParentMessage>();

  return h.input([
    h.Id(id),
    h.Type("text"),
    h.Value(value),
    h.OnInput((value) => onInput(value, index)),
    h.AriaLabel(ariaLabel),
    ...(name === undefined ? [] : [h.Name(name)]),
    h.Attribute("autocomplete", "one-time-code"),
    h.Attribute("inputmode", "numeric"),
    h.Attribute("maxlength", "1"),
    h.Attribute("pattern", "[0-9]*"),
    ...(state.disabled === true ? [h.Disabled(true)] : []),
    ...(state.invalid === true ? [h.Attribute("aria-invalid", "true")] : []),
    ...(value === "" ? [] : [h.DataAttribute("filled", "")]),
    ...stateAttributes(h, state),
    h.Class(classNames(otpFieldInputClassName, className)),
    h.Style(style ?? {}),
  ]);
};

export const separatorView = <ParentMessage>({
  label = "-",
  className,
  style,
}: SeparatorViewConfig): Html => {
  const h = html<ParentMessage>();

  return h.span(
    [
      h.Attribute("aria-hidden", "true"),
      h.Class(classNames(otpFieldSeparatorClassName, className)),
      h.Style(style ?? {}),
    ],
    [label]
  );
};

export const otpFieldRootClassName = "grid max-w-sm gap-2";

export const otpFieldInputGroupClassName =
  "flex items-center gap-2 rounded-lg border border-gray-300 bg-white p-1 shadow-sm data-[disabled]:bg-gray-50";

export const otpFieldInputClassName =
  "size-10 rounded-md border border-gray-200 bg-white text-center text-lg font-semibold tabular-nums text-gray-950 outline-none transition-colors focus:border-accent-500 focus:ring-2 focus:ring-accent-100 disabled:cursor-not-allowed disabled:bg-gray-50 disabled:text-gray-400 data-[filled]:border-gray-300 data-[invalid]:border-red-500 data-[invalid]:focus:ring-red-100";

export const otpFieldSeparatorClassName =
  "px-1 text-lg font-semibold text-gray-400 select-none";

import { Scene } from "foldkit";
import { describe, test } from "vitest";

import * as OtpFieldBasicExample from "../../examples/otp-field-basic/main";

describe("otp-field", () => {
  test("renders grouped one-time-code inputs with separator anatomy", () => {
    const [model] = OtpFieldBasicExample.init();

    Scene.scene(
      {
        update: OtpFieldBasicExample.update,
        view: OtpFieldBasicExample.view,
      },
      Scene.with(model),
      Scene.expect(
        Scene.role("group", { name: "Verification code" })
      ).toExist(),
      Scene.expect(Scene.role("textbox", { name: "Digit 1" })).toHaveAttr(
        "autocomplete",
        "one-time-code"
      ),
      Scene.expect(Scene.text("-")).toExist()
    );
  });

  test("updates one slot and normalizes pasted code input", () => {
    const [model] = OtpFieldBasicExample.init();
    const FocusSecondDigit = OtpFieldBasicExample.FocusDigit({
      id: "verification-code-1",
    });
    const FocusFifthDigit = OtpFieldBasicExample.FocusDigit({
      id: "verification-code-4",
    });

    Scene.scene(
      {
        update: OtpFieldBasicExample.update,
        view: OtpFieldBasicExample.view,
      },
      Scene.with(model),
      Scene.type(Scene.role("textbox", { name: "Digit 1" }), "4"),
      Scene.Command.expectExact(FocusSecondDigit),
      Scene.Command.resolve(
        FocusSecondDigit,
        OtpFieldBasicExample.CompletedFocusDigit({
          id: "verification-code-1",
        })
      ),
      Scene.expect(Scene.text("Code: 4")).toExist(),
      Scene.type(Scene.role("textbox", { name: "Digit 2" }), "56x7"),
      Scene.Command.expectExact(FocusFifthDigit),
      Scene.Command.resolve(
        FocusFifthDigit,
        OtpFieldBasicExample.CompletedFocusDigit({
          id: "verification-code-4",
        })
      ),
      Scene.expect(Scene.text("Code: 4567")).toExist()
    );
  });
});
